{
  "items": [
    {
      "name": "Finset.mem_finsupp_iff",
      "module_name": "Mathlib.Data.Finset.Finsupp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} [inst : Zero α] {s : Finset ι} {f : ι →₀ α} {t : ι → Finset α},\n  f ∈ s.finsupp t ↔ f.support ⊆ s ∧ ∀ i ∈ s, f i ∈ t i"
    },
    {
      "name": "Finset.mem_dfinsupp_iff",
      "module_name": "Mathlib.Data.DFinsupp.Interval",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : ι → Type u_2} [inst : DecidableEq ι] [inst_1 : (i : ι) → Zero (α i)] {s : Finset ι}\n  {f : Π₀ (i : ι), α i} {t : (i : ι) → Finset (α i)} [inst_2 : (i : ι) → DecidableEq (α i)],\n  f ∈ s.dfinsupp t ↔ f.support ⊆ s ∧ ∀ i ∈ s, f i ∈ t i"
    },
    {
      "name": "Finsupp.support_subset_iff",
      "module_name": "Mathlib.Data.Finsupp.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {M : Type u_4} [inst : Zero M] {s : Set α} {f : α →₀ M}, ↑f.support ⊆ s ↔ ∀ a ∉ s, f a = 0"
    },
    {
      "name": "DFinsupp.rangeIcc",
      "module_name": "Mathlib.Data.DFinsupp.Interval",
      "kind": "definition",
      "type": "{ι : Type u_1} →\n  {α : ι → Type u_2} →\n    [inst : (i : ι) → Zero (α i)] →\n      [inst_1 : (i : ι) → PartialOrder (α i)] →\n        [(i : ι) → LocallyFiniteOrder (α i)] → (Π₀ (i : ι), α i) → (Π₀ (i : ι), α i) → Π₀ (i : ι), Finset (α i)"
    },
    {
      "name": "Finsupp.supported",
      "module_name": "Mathlib.LinearAlgebra.Finsupp.Supported",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  (M : Type u_2) →\n    (R : Type u_5) →\n      [inst : Semiring R] → [inst_1 : AddCommMonoid M] → [inst_2 : Module R M] → Set α → Submodule R (α →₀ M)"
    },
    {
      "name": "DFinsupp.support_subset_iff",
      "module_name": "Mathlib.Data.DFinsupp.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u} {β : ι → Type v} [inst : DecidableEq ι] [inst_1 : (i : ι) → Zero (β i)]\n  [inst_2 : (i : ι) → (x : β i) → Decidable (x ≠ 0)] {s : Set ι} {f : Π₀ (i : ι), β i},\n  ↑f.support ⊆ s ↔ ∀ i ∉ s, f i = 0"
    },
    {
      "name": "Finsupp.rangeIcc",
      "module_name": "Mathlib.Data.Finsupp.Interval",
      "kind": "definition",
      "type": "{ι : Type u_1} →\n  {α : Type u_2} →\n    [inst : Zero α] →\n      [inst_1 : PartialOrder α] → [LocallyFiniteOrder α] → [DecidableEq ι] → (ι →₀ α) → (ι →₀ α) → ι →₀ Finset α"
    },
    {
      "name": "Finsupp.support",
      "module_name": "Mathlib.Data.Finsupp.Defs",
      "kind": "definition",
      "type": "{α : Type u_9} → {M : Type u_10} → [inst : Zero M] → (α →₀ M) → Finset α"
    }
  ]
}

